INSERT INTO "Article" ("title", "titleAr", "slug", "content", "coverImage", "publishedAt", "updatedAt", "categoryId", "authorId", "isDraft", "isFeatured")
SELECT 'Qassem: Lebanon Faces Its Most Dangerous Phase... “The Victory of Steadfastness” Remains Our Standard',
       'قاسم: لبنان يواجه أخطر مراحله... "انتصار الصمود" يبقى شعارنا',
       'qassem-lb-speech-19626',
       $c${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "أكد الأمين العام لحزب الله نعيم قاسم أن لبنان يمر في أخطر مرحلة من تاريخه، معتبراً أن البلاد تواجه ما وصفه بـ«أخطر مشروع أميركي – إسرائيلي» يستهدف المقاومة ومستقبل لبنان.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وفي خطاب اتسم بالتشديد على الصمود والثبات رغم التطورات الميدانية الأخيرة، رأى قاسم أن النصر لا يُقاس فقط بالنتائج العسكرية المباشرة، بل بقدرة المقاومة على الاستمرار ومنع خصومها من تحقيق أهدافهم، معتبراً أن «غلبة الثبات» هي أحد أشكال الانتصار.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وقال إن مشروع إنهاء حزب الله وتثبيت الاحتلال فشل في تحقيق غاياته، مؤكداً أن المقاومة خاضت خلال الأشهر الماضية مواجهة طويلة وأن «15 شهراً من الصبر كانت قتالاً»، وفق تعبيره.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "كما شدد على أن الحزب وضع خطة طويلة الأمد للتعامل مع المرحلة المقبلة، وأنه غير معني بالعودة إلى ما قبل الثاني من آذار، مؤكداً أن هدف إخراج إسرائيل من الأراضي اللبنانية المحتلة سيبقى قائماً.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وتحدث قاسم عن ضغوط إقليمية ودولية رافقت الحرب، معتبراً أن خصوم المقاومة سعوا إلى توسيع دائرة المواجهة وإحداث تغييرات في موازين القوى داخل لبنان والمنطقة، إلا أنهم لم ينجحوا في تحقيق ما أرادوا.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "وختم بالتأكيد أن المقاومة ستواصل نهجها الحالي، داعياً جمهورها إلى التمسك بخيار الصمود والثقة بأن النتائج النهائية ستصب في مصلحتها.", "type": "text"}]}, {"type": "horizontalRule"}, {"type": "paragraph", "content": [{"text": "Naim Qassem stated that Lebanon is going through the most dangerous period in its history, arguing that the country is confronting what he described as the most dangerous American-Israeli project targeting the resistance and Lebanon’s future.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a speech emphasizing resilience and perseverance despite recent battlefield developments, Qassem said that victory should not be measured solely by direct military outcomes, but also by the ability of a resistance movement to endure and prevent its opponents from achieving their objectives. He described the “victory of steadfastness” as a form of success.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He argued that efforts to eliminate Hezbollah and entrench the occupation had failed to achieve their goals, adding that the resistance had endured a long confrontation over recent months and that “15 months of patience was itself a form of fighting.”", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Qassem also stressed that Hezbollah has prepared a long-term strategy for the next phase and is not concerned with returning to the situation that existed before March 2, maintaining that the objective of removing Israel from occupied Lebanese territory remains unchanged.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He further spoke of regional and international pressures accompanying the war, claiming that opponents of the resistance sought to widen the confrontation and reshape the balance of power in Lebanon and the region, but had failed to achieve their aims.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "He concluded by affirming that the resistance would continue along its current path, urging supporters to remain steadfast and confident that the final outcome would ultimately serve their interests.", "type": "text"}]}]}$c$::jsonb,
       'https://kiyksrzefkxjntpk.public.blob.vercel-storage.com/covers/G62GCG43PRLVTIIXT2OVRJRD5Q-8HttBQneCarBzs20UXivbchgQrdYWI.jpg',
       TIMESTAMP '2026-06-19 16:15:11.843',
       CURRENT_TIMESTAMP,
       (SELECT "id" FROM "Category" WHERE "slug" = 'politics'),
       (SELECT "id" FROM "Author" WHERE "slug" = 'hani-a'),
       false,
       false
ON CONFLICT ("slug") DO NOTHING;

-- Live updates, oldest first (10 minutes apart). The daily clean-up removes them after 48 hours.
INSERT INTO "QuickUpdate" ("textAr", "textEn", "isBreaking", "createdAt") VALUES
    ('رئيس الفيفا جياني إنفانتينو: «صباح الخير يا لبنان»', 'FIFA President Gianni Infantino: ‘Good morning, Lebanon!’', false, CURRENT_TIMESTAMP - INTERVAL '40 minutes'),
    ('وزيرة التربية: الحكومة تعمل على تنظيم القطاع العام وتنفيذ توصيات الجهات المانحة، ومندوب عنها يتفاوض مع رابطة التعليم الثانوي لتعليق الإضراب، مؤكدة: «ممنوع على أي أحد أن يأخذ الطلاب رهينة»', 'Education Minister: The government is working to reform the public sector and implement donors’ recommendations. A representative is negotiating with the Secondary Education League to suspend the strike. She stressed: ‘No one is allowed to hold students hostage.’', false, CURRENT_TIMESTAMP - INTERVAL '30 minutes'),
    ('رابطة التعليم الثانوي: لا توجد أي مفاوضات مع ممثلين عن وزارة التربية كما ذُكر، والإضراب مستمر غداً', 'Secondary Education League: There are no negotiations with representatives of the Education Ministry, contrary to what was stated, and the strike will continue tomorrow', false, CURRENT_TIMESTAMP - INTERVAL '20 minutes'),
    ('أسوشيتد برس: سوريا تقرّر الانضمام إلى «تحالف مكة»', 'Associated Press: Syria decides to join the ‘Mecca Alliance’', false, CURRENT_TIMESTAMP - INTERVAL '10 minutes'),
    ('رابطة التعليم الثانوي: استمرار الإضراب غداً الثلاثاء مع اعتصام حاشد الساعة 10:30 صباحاً أمام وزارة التربية – الأونيسكو', 'Secondary Education League: The strike will continue tomorrow, Tuesday, with a large sit-in at 10:30 AM outside the Ministry of Education in UNESCO', false, CURRENT_TIMESTAMP - INTERVAL '0 minutes');
